--[@tSQLt:NoTransaction](DEFAULT)
CREATE PROCEDURE [AgreedTests].[test 04 [A04 two invoice lines whose descriptions differ only in case are both written]
AS
BEGIN
  DELETE FROM [Sales].[Orders];
  DELETE FROM [Sales].[OrderLines];
  DELETE FROM [Warehouse].[StockItems];
  DELETE FROM [Warehouse].[StockItemHoldings];
  DELETE FROM [Sales].[Customers];
